// aplicar-fase2.mjs: escribe los archivos de la Fase 2 en tu repositorio.
// Ejecútalo desde la RAIZ del proyecto:  node aplicar-fase2.mjs
import { existsSync, mkdirSync, renameSync, writeFileSync, readdirSync } from "node:fs";
import { dirname } from "node:path";

if (!existsSync("package.json") || !existsSync("prisma")) {
  console.error("Ejecuta este script desde la raíz del proyecto (donde está package.json).");
  process.exit(1);
}

// 1) Mueve app/ -> src/app/ (si existe app/ en la raíz, Next.js ignoraría src/app).
mkdirSync("src/app", { recursive: true });
for (const f of ["layout.tsx", "page.tsx", "globals.css", "favicon.ico"]) {
  if (existsSync(`app/${f}`) && !existsSync(`src/app/${f}`)) {
    renameSync(`app/${f}`, `src/app/${f}`);
    console.log(`movido  app/${f} -> src/app/${f}`);
  }
}
if (existsSync("app") && readdirSync("app").length === 0) {
  try { (await import("node:fs")).rmdirSync("app"); } catch {}
}

// 2) Escribe los archivos.
const FILES = [{"path": "package.json", "content": "{\n  \"name\": \"tienda-regalos\",\n  \"version\": \"0.1.0\",\n  \"private\": true,\n  \"engines\": {\n    \"node\": \">=22.18\"\n  },\n  \"scripts\": {\n    \"dev\": \"next dev\",\n    \"build\": \"next build\",\n    \"start\": \"next start\",\n    \"lint\": \"eslint\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"node --test \\\"tests/unit/**/*.test.ts\\\"\"\n  },\n  \"dependencies\": {\n    \"next\": \"16.4.0\",\n    \"react\": \"19.3.0\",\n    \"react-dom\": \"19.3.0\"\n  },\n  \"devDependencies\": {\n    \"@tailwindcss/turbopack\": \"^4\",\n    \"@types/node\": \"^20\",\n    \"@types/react\": \"^19\",\n    \"@types/react-dom\": \"^19\",\n    \"eslint\": \"^9\",\n    \"eslint-config-next\": \"16.4.0\",\n    \"prisma\": \"^7.10.0\",\n    \"tailwindcss\": \"^4\",\n    \"typescript\": \"^5\"\n  }\n}\n"}, {"path": "tsconfig.json", "content": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2017\",\n    \"lib\": [\"dom\", \"dom.iterable\", \"esnext\"],\n    \"allowJs\": true,\n    \"skipLibCheck\": true,\n    \"strict\": true,\n    \"noUncheckedIndexedAccess\": true,\n    \"noImplicitOverride\": true,\n    \"erasableSyntaxOnly\": true,\n    \"allowImportingTsExtensions\": true,\n    \"noEmit\": true,\n    \"esModuleInterop\": true,\n    \"module\": \"esnext\",\n    \"moduleResolution\": \"bundler\",\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"jsx\": \"react-jsx\",\n    \"incremental\": true,\n    \"plugins\": [\n      {\n        \"name\": \"next\"\n      }\n    ],\n    \"paths\": {\n      \"@/*\": [\"./src/*\"]\n    }\n  },\n  \"include\": [\n    \"next-env.d.ts\",\n    \"**/*.ts\",\n    \"**/*.tsx\",\n    \".next/types/**/*.ts\",\n    \".next/dev/types/**/*.ts\",\n    \"**/*.mts\"\n  ],\n  \"exclude\": [\"node_modules\"]\n}\n"}, {"path": "src/modules/shared/domain/errors.ts", "content": "/**\n * Errores del dominio compartidos por todos los módulos.\n *\n * ¿Por qué existen?\n * Los casos de uso necesitan comunicar \"qué salió mal\" sin saber nada de HTTP,\n * Prisma o Next.js. Cada error lleva un `code` estable; la capa de presentación\n * (rutas API, Server Actions) lo traduce a un código HTTP o a un mensaje de\n * formulario. Así la regla de negocio vive en un solo lugar y cada borde\n * decide cómo mostrarla.\n *\n * Correspondencia sugerida con HTTP (se implementa en la capa de presentación):\n *   VALIDATION    -> 400\n *   NOT_FOUND     -> 404\n *   CONFLICT      -> 409\n *   BUSINESS_RULE -> 422\n *\n * Este archivo es un \"shared kernel\": un núcleo pequeño y estable que los\n * módulos pueden compartir sin acoplarse entre sí. No debe crecer con\n * lógica de un módulo concreto.\n */\n\nexport type DomainErrorCode = \"VALIDATION\" | \"NOT_FOUND\" | \"CONFLICT\" | \"BUSINESS_RULE\";\n\n/** Clase base: permite capturar cualquier error de negocio con `instanceof DomainError`. */\nexport class DomainError extends Error {\n  readonly code: DomainErrorCode;\n\n  constructor(code: DomainErrorCode, message: string) {\n    super(message);\n    // `new.target.name` deja el nombre de la subclase (útil en logs y pruebas).\n    this.name = new.target.name;\n    this.code = code;\n  }\n}\n\n/** Un dato de entrada no cumple las reglas del dominio (vacío, formato, rango...). */\nexport class ValidationError extends DomainError {\n  /** Campo afectado, para que el formulario pueda marcarlo. */\n  readonly field: string | undefined;\n\n  constructor(message: string, field?: string) {\n    super(\"VALIDATION\", message);\n    this.field = field;\n  }\n}\n\n/** El recurso solicitado no existe. */\nexport class NotFoundError extends DomainError {\n  constructor(entity: string, identifier: string) {\n    super(\"NOT_FOUND\", `${entity} no encontrado: ${identifier}`);\n  }\n}\n\n/** La operación choca con el estado actual (p. ej. un slug que ya está en uso). */\nexport class ConflictError extends DomainError {\n  constructor(message: string) {\n    super(\"CONFLICT\", message);\n  }\n}\n\n/** Una regla de negocio impide la operación (p. ej. usar una categoría inactiva). */\nexport class BusinessRuleError extends DomainError {\n  constructor(message: string) {\n    super(\"BUSINESS_RULE\", message);\n  }\n}\n"}, {"path": "src/modules/shared/domain/slug.ts", "content": "/**\n * Utilidades para trabajar con \"slugs\": identificadores legibles para URLs\n * (por ejemplo `caja-de-chocolates`) que usan las páginas /productos/[slug]\n * y /categorias/[slug].\n *\n * Son funciones puras (sin I/O), por eso viven en el dominio y se prueban\n * sin base de datos.\n *\n * Seguridad: restringir el slug a `a-z`, `0-9` y guiones evita que un valor\n * malicioso termine en una URL o en una ruta de archivo con caracteres\n * peligrosos. La unicidad NO se garantiza aquí: la comprueban los casos de uso\n * y, en última instancia, la restricción UNIQUE de PostgreSQL.\n */\n\nimport { ValidationError } from \"./errors.ts\";\n\nexport const SLUG_MAX_LENGTH = 80;\n\nconst SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;\n\n/**\n * Convierte un texto libre en un slug.\n * Quita tildes (\"Ñandú\" -> \"nandu\"), pasa a minúsculas y reemplaza\n * cualquier secuencia no alfanumérica por un único guion.\n * Devuelve \"\" si el texto no contiene ningún carácter aprovechable.\n */\nexport function slugify(text: string): string {\n  return text\n    .normalize(\"NFD\")\n    .replace(/[̀-ͯ]/g, \"\")\n    .toLowerCase()\n    .replace(/[^a-z0-9]+/g, \"-\")\n    .replace(/^-+|-+$/g, \"\")\n    .slice(0, SLUG_MAX_LENGTH)\n    .replace(/-+$/, \"\");\n}\n\nexport function isValidSlug(slug: string): boolean {\n  return slug.length > 0 && slug.length <= SLUG_MAX_LENGTH && SLUG_PATTERN.test(slug);\n}\n\n/**\n * Decide el slug definitivo de una entidad.\n *\n * - Si el usuario envió uno explícito, se valida tal cual (no se \"arregla\" en silencio).\n * - Si no, se deriva del nombre.\n *\n * @throws ValidationError si el slug explícito es inválido o no se puede derivar uno.\n */\nexport function resolveSlug(explicitSlug: string | undefined, nameSource: string): string {\n  const explicit = explicitSlug?.trim();\n\n  if (explicit) {\n    if (!isValidSlug(explicit)) {\n      throw new ValidationError(\n        `El slug solo admite minúsculas, números y guiones (máx. ${SLUG_MAX_LENGTH} caracteres).`,\n        \"slug\",\n      );\n    }\n    return explicit;\n  }\n\n  const derived = slugify(nameSource);\n  if (!derived) {\n    throw new ValidationError(\"No se pudo generar un slug a partir del nombre.\", \"slug\");\n  }\n  return derived;\n}\n"}, {"path": "src/modules/categories/domain/category.ts", "content": "/**\n * Entidad `Category` y reglas de negocio de las categorías.\n *\n * Pertenece al dominio: no importa Prisma, Next.js ni React. Si mañana cambia la\n * base de datos o el framework, este archivo no cambia.\n *\n * Las categorías nunca se borran: se DESACTIVAN (`isActive = false`). Motivo:\n * los productos las referencian con una clave foránea y borrar una categoría\n * con productos dejaría el catálogo roto u obligaría a borrar productos en\n * cascada, una pérdida de datos que nadie pidió. Desactivarla la oculta de la\n * tienda y bloquea nuevos productos en ella, sin destruir nada.\n */\n\nimport { ValidationError } from \"../../shared/domain/errors.ts\";\n\nexport const CATEGORY_NAME_MAX_LENGTH = 80;\nexport const CATEGORY_DESCRIPTION_MAX_LENGTH = 500;\n\n/** Categoría tal como existe en el negocio (ya persistida). */\nexport interface Category {\n  id: string;\n  name: string;\n  slug: string;\n  description: string | null;\n  isActive: boolean;\n  createdAt: Date;\n  updatedAt: Date;\n}\n\n/** Datos necesarios para crear una categoría. El id y las fechas los asigna la persistencia. */\nexport interface NewCategory {\n  name: string;\n  slug: string;\n  description: string | null;\n  isActive: boolean;\n}\n\n/** Cambios parciales permitidos al actualizar. Solo se aplican las claves presentes. */\nexport interface CategoryChanges {\n  name?: string;\n  slug?: string;\n  description?: string | null;\n  isActive?: boolean;\n}\n\n/**\n * Limpia y valida el nombre: recorta espacios, colapsa espacios internos\n * y rechaza vacíos o demasiado largos.\n */\nexport function normalizeCategoryName(raw: string): string {\n  const name = raw.trim().replace(/\\s+/g, \" \");\n  if (!name) {\n    throw new ValidationError(\"El nombre de la categoría es obligatorio.\", \"name\");\n  }\n  if (name.length > CATEGORY_NAME_MAX_LENGTH) {\n    throw new ValidationError(\n      `El nombre no puede superar ${CATEGORY_NAME_MAX_LENGTH} caracteres.`,\n      \"name\",\n    );\n  }\n  return name;\n}\n\n/** La descripción es opcional: un texto vacío se guarda como `null`. */\nexport function normalizeCategoryDescription(raw: string | null | undefined): string | null {\n  const description = raw?.trim() ?? \"\";\n  if (!description) return null;\n  if (description.length > CATEGORY_DESCRIPTION_MAX_LENGTH) {\n    throw new ValidationError(\n      `La descripción no puede superar ${CATEGORY_DESCRIPTION_MAX_LENGTH} caracteres.`,\n      \"description\",\n    );\n  }\n  return description;\n}\n"}, {"path": "src/modules/categories/domain/category-repository.ts", "content": "/**\n * Contrato de persistencia de categorías.\n *\n * Inversión de dependencias: los casos de uso (capa `application`) dependen de\n * ESTA interfaz, no de Prisma. La implementación concreta\n * (`PrismaCategoryRepository`, Fase 3) vive en `infrastructure` y se inyecta\n * desde fuera. Gracias a esto las pruebas unitarias usan un repositorio en\n * memoria y no necesitan base de datos.\n */\n\nimport type { Category, CategoryChanges, NewCategory } from \"./category.ts\";\n\nexport interface ListCategoriesOptions {\n  /** Si es `true`, solo devuelve categorías activas (uso típico: la tienda pública). */\n  onlyActive?: boolean;\n}\n\nexport interface CategoryRepository {\n  findById(id: string): Promise<Category | null>;\n  findBySlug(slug: string): Promise<Category | null>;\n  findAll(options?: ListCategoriesOptions): Promise<Category[]>;\n\n  /**\n   * Guarda una categoría nueva y devuelve la entidad con id y fechas.\n   * @throws ConflictError si el slug ya existe (la restricción UNIQUE de la base\n   *         de datos es la garantía final, incluso ante peticiones concurrentes).\n   */\n  create(data: NewCategory): Promise<Category>;\n\n  /**\n   * Aplica cambios parciales.\n   * @throws NotFoundError si la categoría no existe.\n   * @throws ConflictError si el nuevo slug ya existe.\n   */\n  update(id: string, changes: CategoryChanges): Promise<Category>;\n}\n"}, {"path": "src/modules/categories/application/create-category.ts", "content": "/**\n * Caso de uso: crear una categoría.\n *\n * Capa `application`: coordina reglas del dominio y el repositorio, pero no sabe\n * si lo llama una ruta API, una Server Action o una prueba. Ese es justamente el\n * punto: la regla se escribe una vez y se reutiliza desde cualquier borde.\n *\n * Autorización: este caso de uso NO verifica quién llama. Esa responsabilidad es\n * de la capa de presentación (`requireAdmin()` en la Fase 4), que debe ejecutarse\n * ANTES de invocar cualquier operación de escritura.\n *\n * Unicidad del slug: se comprueba aquí para dar un error claro, pero dos\n * peticiones simultáneas podrían pasar la comprobación a la vez. Por eso la base\n * de datos también tiene un índice UNIQUE y el repositorio traduce esa violación\n * a `ConflictError`.\n */\n\nimport { ConflictError } from \"../../shared/domain/errors.ts\";\nimport { resolveSlug } from \"../../shared/domain/slug.ts\";\nimport {\n  normalizeCategoryDescription,\n  normalizeCategoryName,\n  type Category,\n} from \"../domain/category.ts\";\nimport type { CategoryRepository } from \"../domain/category-repository.ts\";\n\nexport interface CreateCategoryInput {\n  name: string;\n  /** Opcional: si se omite se deriva del nombre. */\n  slug?: string;\n  description?: string | null;\n}\n\nexport class CreateCategory {\n  private readonly categories: CategoryRepository;\n\n  constructor(deps: { categories: CategoryRepository }) {\n    this.categories = deps.categories;\n  }\n\n  /**\n   * @throws ValidationError si el nombre, slug o descripción no son válidos.\n   * @throws ConflictError si ya existe una categoría con ese slug.\n   */\n  async execute(input: CreateCategoryInput): Promise<Category> {\n    // Se revalida aunque la ruta ya use Zod: el dominio no confía en quien lo llama.\n    const name = normalizeCategoryName(input.name);\n    const slug = resolveSlug(input.slug, name);\n    const description = normalizeCategoryDescription(input.description);\n\n    if (await this.categories.findBySlug(slug)) {\n      throw new ConflictError(`Ya existe una categoría con el slug \"${slug}\".`);\n    }\n\n    return this.categories.create({ name, slug, description, isActive: true });\n  }\n}\n"}, {"path": "src/modules/categories/application/get-category-by-id.ts", "content": "/**\n * Caso de uso: obtener una categoría por su identificador.\n *\n * Lo usa el panel administrativo (formularios de edición). Devuelve la\n * categoría aunque esté inactiva: el panel debe poder verla y reactivarla.\n * Quien exponga datos al público (la tienda) debe comprobar `isActive` y\n * responder 404 si es `false`; esa decisión de visibilidad pertenece a la\n * capa de presentación, no a este caso de uso.\n */\n\nimport { NotFoundError } from \"../../shared/domain/errors.ts\";\nimport type { Category } from \"../domain/category.ts\";\nimport type { CategoryRepository } from \"../domain/category-repository.ts\";\n\nexport class GetCategoryById {\n  private readonly categories: CategoryRepository;\n\n  constructor(deps: { categories: CategoryRepository }) {\n    this.categories = deps.categories;\n  }\n\n  /** @throws NotFoundError si la categoría no existe. */\n  async execute(id: string): Promise<Category> {\n    const category = await this.categories.findById(id);\n    if (!category) throw new NotFoundError(\"Categoría\", id);\n    return category;\n  }\n}\n"}, {"path": "src/modules/categories/application/get-category-by-slug.ts", "content": "/**\n * Caso de uso: obtener una categoría por su slug.\n *\n * Lo usa la tienda pública en /categorias/[slug]. Igual que `GetCategoryById`,\n * devuelve también categorías inactivas; la página pública debe responder 404\n * cuando `isActive` sea `false`.\n */\n\nimport { NotFoundError } from \"../../shared/domain/errors.ts\";\nimport type { Category } from \"../domain/category.ts\";\nimport type { CategoryRepository } from \"../domain/category-repository.ts\";\n\nexport class GetCategoryBySlug {\n  private readonly categories: CategoryRepository;\n\n  constructor(deps: { categories: CategoryRepository }) {\n    this.categories = deps.categories;\n  }\n\n  /** @throws NotFoundError si la categoría no existe. */\n  async execute(slug: string): Promise<Category> {\n    const category = await this.categories.findBySlug(slug);\n    if (!category) throw new NotFoundError(\"Categoría\", slug);\n    return category;\n  }\n}\n"}, {"path": "src/modules/categories/application/list-categories.ts", "content": "/**\n * Caso de uso: listar categorías.\n *\n * - Tienda pública: `execute({ onlyActive: true })`.\n * - Panel administrativo: `execute()` para ver también las inactivas.\n *\n * Quien llama decide el filtro; no se asume por defecto que el visitante es\n * público para no mezclar permisos con consultas.\n */\n\nimport type { Category } from \"../domain/category.ts\";\nimport type {\n  CategoryRepository,\n  ListCategoriesOptions,\n} from \"../domain/category-repository.ts\";\n\nexport class ListCategories {\n  private readonly categories: CategoryRepository;\n\n  constructor(deps: { categories: CategoryRepository }) {\n    this.categories = deps.categories;\n  }\n\n  async execute(options: ListCategoriesOptions = {}): Promise<Category[]> {\n    return this.categories.findAll(options);\n  }\n}\n"}, {"path": "src/modules/categories/application/update-category.ts", "content": "/**\n * Caso de uso: actualizar nombre, slug o descripción de una categoría.\n *\n * Decisión de diseño: el slug NO se regenera cuando cambia el nombre. Cambiar\n * una URL pública rompe enlaces compartidos y el posicionamiento en buscadores.\n * El slug solo cambia si quien edita lo envía de forma explícita.\n *\n * El estado activo/inactivo no se modifica aquí; tiene sus propios casos de uso\n * (`DeactivateCategory` / `ReactivateCategory`) para que la intención quede clara\n * en el código y en los registros de auditoría futuros.\n */\n\nimport { ConflictError, NotFoundError } from \"../../shared/domain/errors.ts\";\nimport { resolveSlug } from \"../../shared/domain/slug.ts\";\nimport {\n  normalizeCategoryDescription,\n  normalizeCategoryName,\n  type Category,\n  type CategoryChanges,\n} from \"../domain/category.ts\";\nimport type { CategoryRepository } from \"../domain/category-repository.ts\";\n\nexport interface UpdateCategoryInput {\n  name?: string;\n  slug?: string;\n  /** `null` o texto vacío borra la descripción; `undefined` la deja igual. */\n  description?: string | null;\n}\n\nexport class UpdateCategory {\n  private readonly categories: CategoryRepository;\n\n  constructor(deps: { categories: CategoryRepository }) {\n    this.categories = deps.categories;\n  }\n\n  /**\n   * @throws NotFoundError si la categoría no existe.\n   * @throws ValidationError si algún dato es inválido.\n   * @throws ConflictError si el nuevo slug pertenece a otra categoría.\n   */\n  async execute(id: string, input: UpdateCategoryInput): Promise<Category> {\n    const current = await this.categories.findById(id);\n    if (!current) throw new NotFoundError(\"Categoría\", id);\n\n    const changes: CategoryChanges = {};\n\n    if (input.name !== undefined) {\n      changes.name = normalizeCategoryName(input.name);\n    }\n\n    if (input.description !== undefined) {\n      changes.description = normalizeCategoryDescription(input.description);\n    }\n\n    if (input.slug !== undefined) {\n      // Se valida el formato del slug enviado (no se deriva del nombre).\n      const slug = resolveSlug(input.slug, changes.name ?? current.name);\n      if (slug !== current.slug) {\n        const owner = await this.categories.findBySlug(slug);\n        if (owner && owner.id !== id) {\n          throw new ConflictError(`Ya existe una categoría con el slug \"${slug}\".`);\n        }\n        changes.slug = slug;\n      }\n    }\n\n    // Sin cambios reales: se evita una escritura innecesaria.\n    if (Object.keys(changes).length === 0) return current;\n\n    return this.categories.update(id, changes);\n  }\n}\n"}, {"path": "src/modules/categories/application/set-category-status.ts", "content": "/**\n * Casos de uso: desactivar y reactivar una categoría.\n *\n * ¿Qué pasa con los productos de una categoría desactivada?\n * Decisión: NO se tocan. Siguen existiendo en la base de datos y el panel\n * administrativo puede verlos y moverlos a otra categoría. La tienda pública\n * los oculta porque su consulta exige que la categoría esté activa\n * (`publicOnly` en `ProductRepository`). Reactivar la categoría los hace\n * visibles de nuevo sin perder información.\n *\n * Ambas operaciones son idempotentes: repetirlas no produce error ni escritura.\n */\n\nimport { NotFoundError } from \"../../shared/domain/errors.ts\";\nimport type { Category } from \"../domain/category.ts\";\nimport type { CategoryRepository } from \"../domain/category-repository.ts\";\n\nasync function setActive(\n  categories: CategoryRepository,\n  id: string,\n  isActive: boolean,\n): Promise<Category> {\n  const current = await categories.findById(id);\n  if (!current) throw new NotFoundError(\"Categoría\", id);\n  if (current.isActive === isActive) return current;\n  return categories.update(id, { isActive });\n}\n\nexport class DeactivateCategory {\n  private readonly categories: CategoryRepository;\n\n  constructor(deps: { categories: CategoryRepository }) {\n    this.categories = deps.categories;\n  }\n\n  /** @throws NotFoundError si la categoría no existe. */\n  execute(id: string): Promise<Category> {\n    return setActive(this.categories, id, false);\n  }\n}\n\nexport class ReactivateCategory {\n  private readonly categories: CategoryRepository;\n\n  constructor(deps: { categories: CategoryRepository }) {\n    this.categories = deps.categories;\n  }\n\n  /** @throws NotFoundError si la categoría no existe. */\n  execute(id: string): Promise<Category> {\n    return setActive(this.categories, id, true);\n  }\n}\n"}, {"path": "src/modules/products/domain/product.ts", "content": "/**\n * Entidad `Product` y reglas de negocio de los productos.\n *\n * Pertenece al dominio: no depende de Prisma, Next.js, AWS ni React.\n *\n * DINERO: el precio se guarda como número ENTERO en centavos de peso colombiano\n * (`priceInCents`). Nunca como `float`: 0.1 + 0.2 !== 0.3 en coma flotante y\n * esos errores de redondeo son inaceptables al cobrar. Ejemplo: $45.900 COP se\n * guarda como 4_590_000. La conversión a texto (\"$45.900\") es un asunto de\n * presentación y se hace en la interfaz, no aquí.\n *\n * LÍMITE SUPERIOR: PostgreSQL `INTEGER` (el tipo `Int` de Prisma) admite hasta\n * 2.147.483.647. Fijamos 2.000.000.000 centavos (= $20.000.000 COP) como tope, lo\n * suficientemente alto para un regalo y garantizado de caber en la columna. Si\n * algún día se necesitan precios mayores, se migra la columna a BigInt y se\n * ajusta SOLO esta constante.\n */\n\nimport { ValidationError } from \"../../shared/domain/errors.ts\";\n\nexport const PRODUCT_NAME_MAX_LENGTH = 120;\nexport const PRODUCT_DESCRIPTION_MAX_LENGTH = 2000;\nexport const PRODUCT_PRICE_MAX_IN_CENTS = 2_000_000_000;\nexport const PRODUCT_IMAGE_URL_MAX_LENGTH = 2048;\n\n/** Producto tal como existe en el negocio (ya persistido). */\nexport interface Product {\n  id: string;\n  name: string;\n  slug: string;\n  description: string;\n  /** Precio en centavos de COP. Entero positivo. */\n  priceInCents: number;\n  categoryId: string;\n  imageUrl: string | null;\n  /** `false` = oculto en la tienda (sin stock o retirado), pero conservado. */\n  isAvailable: boolean;\n  createdAt: Date;\n  updatedAt: Date;\n}\n\n/** Datos para crear un producto. El id y las fechas los asigna la persistencia. */\nexport interface NewProduct {\n  name: string;\n  slug: string;\n  description: string;\n  priceInCents: number;\n  categoryId: string;\n  imageUrl: string | null;\n  isAvailable: boolean;\n}\n\n/** Cambios parciales permitidos al actualizar. Solo se aplican las claves presentes. */\nexport interface ProductChanges {\n  name?: string;\n  slug?: string;\n  description?: string;\n  priceInCents?: number;\n  categoryId?: string;\n  imageUrl?: string | null;\n  isAvailable?: boolean;\n}\n\n/**\n * Valida el precio. Rechaza decimales, cero, negativos, NaN/Infinity y valores\n * por encima del tope. `Number.isInteger` ya descarta NaN e Infinity.\n */\nexport function validatePriceInCents(value: number): number {\n  if (!Number.isInteger(value)) {\n    throw new ValidationError(\"El precio debe ser un número entero de centavos.\", \"priceInCents\");\n  }\n  if (value <= 0) {\n    throw new ValidationError(\"El precio debe ser mayor que cero.\", \"priceInCents\");\n  }\n  if (value > PRODUCT_PRICE_MAX_IN_CENTS) {\n    throw new ValidationError(\"El precio supera el máximo permitido.\", \"priceInCents\");\n  }\n  return value;\n}\n\nexport function normalizeProductName(raw: string): string {\n  const name = raw.trim().replace(/\\s+/g, \" \");\n  if (!name) {\n    throw new ValidationError(\"El nombre del producto es obligatorio.\", \"name\");\n  }\n  if (name.length > PRODUCT_NAME_MAX_LENGTH) {\n    throw new ValidationError(\n      `El nombre no puede superar ${PRODUCT_NAME_MAX_LENGTH} caracteres.`,\n      \"name\",\n    );\n  }\n  return name;\n}\n\n/** La descripción puede quedar vacía, pero no excede el máximo. */\nexport function normalizeProductDescription(raw: string | undefined): string {\n  const description = raw?.trim() ?? \"\";\n  if (description.length > PRODUCT_DESCRIPTION_MAX_LENGTH) {\n    throw new ValidationError(\n      `La descripción no puede superar ${PRODUCT_DESCRIPTION_MAX_LENGTH} caracteres.`,\n      \"description\",\n    );\n  }\n  return description;\n}\n\n/**\n * Valida la URL de la imagen. Solo se aceptan `https:` y `http:`; esquemas como\n * `javascript:` o `data:` se rechazan porque acabarían en un atributo `src`/`href`\n * de la tienda (riesgo de XSS). Vacío o `null` significa \"sin imagen\".\n */\nexport function normalizeImageUrl(raw: string | null | undefined): string | null {\n  const value = raw?.trim() ?? \"\";\n  if (!value) return null;\n\n  if (value.length > PRODUCT_IMAGE_URL_MAX_LENGTH) {\n    throw new ValidationError(\"La URL de la imagen es demasiado larga.\", \"imageUrl\");\n  }\n\n  let parsed: URL;\n  try {\n    parsed = new URL(value);\n  } catch {\n    throw new ValidationError(\"La URL de la imagen no es válida.\", \"imageUrl\");\n  }\n\n  if (parsed.protocol !== \"https:\" && parsed.protocol !== \"http:\") {\n    throw new ValidationError(\"La imagen debe usar una URL http o https.\", \"imageUrl\");\n  }\n  return value;\n}\n"}, {"path": "src/modules/products/domain/product-repository.ts", "content": "/**\n * Contrato de persistencia de productos.\n *\n * El dominio y los casos de uso dependen de esta abstracción; la implementación\n * con Prisma (`PrismaProductRepository`, Fase 3) vive en `infrastructure`.\n */\n\nimport type { NewProduct, Product, ProductChanges } from \"./product.ts\";\n\nexport interface ListProductsOptions {\n  /** Filtra por categoría. */\n  categoryId?: string;\n  /**\n   * Vista de la tienda pública: solo productos disponibles (`isAvailable`) CUYA\n   * categoría esté activa. Sin esta opción (panel admin) se devuelven todos.\n   */\n  publicOnly?: boolean;\n  /** Búsqueda por texto en el nombre (sin distinguir mayúsculas). */\n  search?: string;\n}\n\nexport interface ProductRepository {\n  findById(id: string): Promise<Product | null>;\n  findBySlug(slug: string): Promise<Product | null>;\n  findAll(options?: ListProductsOptions): Promise<Product[]>;\n\n  /**\n   * @throws ConflictError si el slug ya existe (UNIQUE en la base de datos).\n   * @throws NotFoundError si `categoryId` no existe (violación de la clave foránea).\n   */\n  create(data: NewProduct): Promise<Product>;\n\n  /**\n   * @throws NotFoundError si el producto (o la nueva categoría) no existe.\n   * @throws ConflictError si el nuevo slug ya existe.\n   */\n  update(id: string, changes: ProductChanges): Promise<Product>;\n\n  /**\n   * Borra definitivamente el producto.\n   * @throws NotFoundError si no existe.\n   * @throws ConflictError si otros registros lo referencian (p. ej. pedidos futuros).\n   */\n  delete(id: string): Promise<void>;\n}\n"}, {"path": "src/modules/products/application/create-product.ts", "content": "/**\n * Caso de uso: crear un producto.\n *\n * Coordina las reglas de negocio ANTES de guardar:\n *  1. Valida y normaliza los datos (nombre, precio, descripción, imagen, slug).\n *  2. Comprueba que la categoría exista y esté ACTIVA.\n *  3. Comprueba que el slug no esté en uso.\n *  4. Delega la persistencia al repositorio inyectado.\n *\n * Dependencia entre módulos: `products` usa el CONTRATO `CategoryRepository` del\n * dominio de `categories`, nunca su infraestructura. Es la forma permitida de\n * relacionar módulos en un monolito modular: dependencia hacia interfaces.\n *\n * Integridad: aunque aquí se verifique la categoría, la clave foránea en\n * PostgreSQL es la garantía definitiva (otra petición podría borrar o cambiar la\n * categoría entre la comprobación y el guardado).\n *\n * Autorización: la verifica la capa de presentación antes de llamar a este caso\n * de uso (ver `requireAdmin()`, Fase 4).\n */\n\nimport { BusinessRuleError, ConflictError, NotFoundError } from \"../../shared/domain/errors.ts\";\nimport { resolveSlug } from \"../../shared/domain/slug.ts\";\nimport type { CategoryRepository } from \"../../categories/domain/category-repository.ts\";\nimport {\n  normalizeImageUrl,\n  normalizeProductDescription,\n  normalizeProductName,\n  validatePriceInCents,\n  type Product,\n} from \"../domain/product.ts\";\nimport type { ProductRepository } from \"../domain/product-repository.ts\";\n\nexport interface CreateProductInput {\n  name: string;\n  slug?: string;\n  description?: string;\n  /** Centavos de COP. Se valida en el dominio. */\n  priceInCents: number;\n  categoryId: string;\n  imageUrl?: string | null;\n  /** Por defecto `true`. */\n  isAvailable?: boolean;\n}\n\nexport class CreateProduct {\n  private readonly products: ProductRepository;\n  private readonly categories: CategoryRepository;\n\n  constructor(deps: { products: ProductRepository; categories: CategoryRepository }) {\n    this.products = deps.products;\n    this.categories = deps.categories;\n  }\n\n  /**\n   * @throws ValidationError si algún dato es inválido (precio, nombre, slug, imagen).\n   * @throws NotFoundError si la categoría no existe.\n   * @throws BusinessRuleError si la categoría está inactiva.\n   * @throws ConflictError si el slug ya está en uso.\n   */\n  async execute(input: CreateProductInput): Promise<Product> {\n    const name = normalizeProductName(input.name);\n    const priceInCents = validatePriceInCents(input.priceInCents);\n    const description = normalizeProductDescription(input.description);\n    const imageUrl = normalizeImageUrl(input.imageUrl);\n    const slug = resolveSlug(input.slug, name);\n\n    const category = await this.categories.findById(input.categoryId);\n    if (!category) throw new NotFoundError(\"Categoría\", input.categoryId);\n    if (!category.isActive) {\n      throw new BusinessRuleError(\n        `La categoría \"${category.name}\" está inactiva y no admite productos nuevos.`,\n      );\n    }\n\n    if (await this.products.findBySlug(slug)) {\n      throw new ConflictError(`Ya existe un producto con el slug \"${slug}\".`);\n    }\n\n    return this.products.create({\n      name,\n      slug,\n      description,\n      priceInCents,\n      categoryId: category.id,\n      imageUrl,\n      isAvailable: input.isAvailable ?? true,\n    });\n  }\n}\n"}, {"path": "src/modules/products/application/get-product-by-id.ts", "content": "/**\n * Caso de uso: obtener un producto por su identificador.\n *\n * Lo usa el panel administrativo (edición). Devuelve el producto aunque no esté\n * disponible: el administrador debe poder verlo y reactivarlo.\n */\n\nimport { NotFoundError } from \"../../shared/domain/errors.ts\";\nimport type { Product } from \"../domain/product.ts\";\nimport type { ProductRepository } from \"../domain/product-repository.ts\";\n\nexport class GetProductById {\n  private readonly products: ProductRepository;\n\n  constructor(deps: { products: ProductRepository }) {\n    this.products = deps.products;\n  }\n\n  /** @throws NotFoundError si el producto no existe. */\n  async execute(id: string): Promise<Product> {\n    const product = await this.products.findById(id);\n    if (!product) throw new NotFoundError(\"Producto\", id);\n    return product;\n  }\n}\n"}, {"path": "src/modules/products/application/get-product-by-slug.ts", "content": "/**\n * Caso de uso: obtener un producto por su slug.\n *\n * Lo usa la tienda pública en /productos/[slug]. Devuelve el producto aunque no\n * esté disponible o su categoría esté inactiva; la página pública debe\n * responder 404 en esos casos (se implementa en la Fase 5), para que el panel\n * administrativo conserve acceso a todo.\n */\n\nimport { NotFoundError } from \"../../shared/domain/errors.ts\";\nimport type { Product } from \"../domain/product.ts\";\nimport type { ProductRepository } from \"../domain/product-repository.ts\";\n\nexport class GetProductBySlug {\n  private readonly products: ProductRepository;\n\n  constructor(deps: { products: ProductRepository }) {\n    this.products = deps.products;\n  }\n\n  /** @throws NotFoundError si el producto no existe. */\n  async execute(slug: string): Promise<Product> {\n    const product = await this.products.findBySlug(slug);\n    if (!product) throw new NotFoundError(\"Producto\", slug);\n    return product;\n  }\n}\n"}, {"path": "src/modules/products/application/list-products.ts", "content": "/**\n * Caso de uso: listar productos.\n *\n * - Catálogo público: `execute({ publicOnly: true })` (disponibles y con\n *   categoría activa).\n * - Por categoría: `execute({ publicOnly: true, categoryId })`.\n * - Panel administrativo: `execute()` devuelve todo.\n *\n * Paginación: se pospone a propósito. Con un catálogo pequeño añadiría\n * complejidad sin beneficio; cuando crezca se incorpora `page`/`pageSize` aquí\n * y en el repositorio sin cambiar a quienes llaman (parámetros opcionales).\n */\n\nimport type { Product } from \"../domain/product.ts\";\nimport type { ListProductsOptions, ProductRepository } from \"../domain/product-repository.ts\";\n\nexport class ListProducts {\n  private readonly products: ProductRepository;\n\n  constructor(deps: { products: ProductRepository }) {\n    this.products = deps.products;\n  }\n\n  async execute(options: ListProductsOptions = {}): Promise<Product[]> {\n    const search = options.search?.trim();\n    return this.products.findAll({\n      ...options,\n      // Una búsqueda vacía equivale a no filtrar.\n      ...(search ? { search } : { search: undefined }),\n    });\n  }\n}\n"}, {"path": "src/modules/products/application/update-product.ts", "content": "/**\n * Caso de uso: actualizar un producto.\n *\n * Reglas:\n *  - Solo se validan y aplican los campos enviados (actualización parcial).\n *  - El slug NO cambia al renombrar el producto (mantiene estables las URLs\n *    públicas); solo cambia si se envía explícitamente.\n *  - Si se cambia la categoría, la nueva debe existir y estar activa. Si el\n *    producto conserva su categoría, no se exige que siga activa: se puede\n *    seguir editando un producto cuya categoría fue desactivada (por ejemplo,\n *    para moverlo a otra).\n *  - El precio se revalida siempre en el dominio; nunca se confía en el cliente.\n */\n\nimport { BusinessRuleError, ConflictError, NotFoundError } from \"../../shared/domain/errors.ts\";\nimport { resolveSlug } from \"../../shared/domain/slug.ts\";\nimport type { CategoryRepository } from \"../../categories/domain/category-repository.ts\";\nimport {\n  normalizeImageUrl,\n  normalizeProductDescription,\n  normalizeProductName,\n  validatePriceInCents,\n  type Product,\n  type ProductChanges,\n} from \"../domain/product.ts\";\nimport type { ProductRepository } from \"../domain/product-repository.ts\";\n\nexport interface UpdateProductInput {\n  name?: string;\n  slug?: string;\n  description?: string;\n  priceInCents?: number;\n  categoryId?: string;\n  /** `null` o vacío elimina la imagen; `undefined` la deja igual. */\n  imageUrl?: string | null;\n  isAvailable?: boolean;\n}\n\nexport class UpdateProduct {\n  private readonly products: ProductRepository;\n  private readonly categories: CategoryRepository;\n\n  constructor(deps: { products: ProductRepository; categories: CategoryRepository }) {\n    this.products = deps.products;\n    this.categories = deps.categories;\n  }\n\n  /**\n   * @throws NotFoundError si el producto o la nueva categoría no existen.\n   * @throws ValidationError si algún dato es inválido.\n   * @throws BusinessRuleError si la nueva categoría está inactiva.\n   * @throws ConflictError si el nuevo slug pertenece a otro producto.\n   */\n  async execute(id: string, input: UpdateProductInput): Promise<Product> {\n    const current = await this.products.findById(id);\n    if (!current) throw new NotFoundError(\"Producto\", id);\n\n    const changes: ProductChanges = {};\n\n    if (input.name !== undefined) changes.name = normalizeProductName(input.name);\n    if (input.description !== undefined) {\n      changes.description = normalizeProductDescription(input.description);\n    }\n    if (input.priceInCents !== undefined) {\n      changes.priceInCents = validatePriceInCents(input.priceInCents);\n    }\n    if (input.imageUrl !== undefined) changes.imageUrl = normalizeImageUrl(input.imageUrl);\n    if (input.isAvailable !== undefined) changes.isAvailable = input.isAvailable;\n\n    if (input.categoryId !== undefined && input.categoryId !== current.categoryId) {\n      const category = await this.categories.findById(input.categoryId);\n      if (!category) throw new NotFoundError(\"Categoría\", input.categoryId);\n      if (!category.isActive) {\n        throw new BusinessRuleError(\n          `La categoría \"${category.name}\" está inactiva y no admite productos.`,\n        );\n      }\n      changes.categoryId = category.id;\n    }\n\n    if (input.slug !== undefined) {\n      const slug = resolveSlug(input.slug, changes.name ?? current.name);\n      if (slug !== current.slug) {\n        const owner = await this.products.findBySlug(slug);\n        if (owner && owner.id !== id) {\n          throw new ConflictError(`Ya existe un producto con el slug \"${slug}\".`);\n        }\n        changes.slug = slug;\n      }\n    }\n\n    if (Object.keys(changes).length === 0) return current;\n\n    return this.products.update(id, changes);\n  }\n}\n"}, {"path": "src/modules/products/application/deactivate-product.ts", "content": "/**\n * Caso de uso: desactivar un producto (borrado lógico).\n *\n * Es la forma recomendada de \"quitar\" un producto de la tienda: lo oculta\n * (`isAvailable = false`) pero conserva el registro. Cuando existan pedidos,\n * sus líneas seguirán apuntando a un producto real y el historial de ventas no\n * se corrompe. Para eliminarlo de verdad existe `DeleteProduct`.\n *\n * Es idempotente: desactivar algo ya desactivado no produce error ni escritura.\n */\n\nimport { NotFoundError } from \"../../shared/domain/errors.ts\";\nimport type { Product } from \"../domain/product.ts\";\nimport type { ProductRepository } from \"../domain/product-repository.ts\";\n\nexport class DeactivateProduct {\n  private readonly products: ProductRepository;\n\n  constructor(deps: { products: ProductRepository }) {\n    this.products = deps.products;\n  }\n\n  /** @throws NotFoundError si el producto no existe. */\n  async execute(id: string): Promise<Product> {\n    const current = await this.products.findById(id);\n    if (!current) throw new NotFoundError(\"Producto\", id);\n    if (!current.isAvailable) return current;\n    return this.products.update(id, { isAvailable: false });\n  }\n}\n"}, {"path": "src/modules/products/application/delete-product.ts", "content": "/**\n * Caso de uso: eliminar definitivamente un producto.\n *\n * Es destructivo e irreversible, por eso es un caso de uso distinto de\n * `DeactivateProduct`. La interfaz de administración debe pedir confirmación.\n *\n * Cuando se implementen los pedidos, `OrderItem` referenciará a `Product` con\n * `onDelete: Restrict`: PostgreSQL impedirá borrar un producto vendido, y el\n * repositorio lo traducirá a `ConflictError`. En ese caso la acción correcta es\n * desactivarlo. No se borra en cascada para no destruir el historial de ventas.\n */\n\nimport { NotFoundError } from \"../../shared/domain/errors.ts\";\nimport type { ProductRepository } from \"../domain/product-repository.ts\";\n\nexport class DeleteProduct {\n  private readonly products: ProductRepository;\n\n  constructor(deps: { products: ProductRepository }) {\n    this.products = deps.products;\n  }\n\n  /**\n   * @throws NotFoundError si el producto no existe.\n   * @throws ConflictError si otros registros lo referencian.\n   */\n  async execute(id: string): Promise<void> {\n    const current = await this.products.findById(id);\n    if (!current) throw new NotFoundError(\"Producto\", id);\n    await this.products.delete(id);\n  }\n}\n"}, {"path": "tests/unit/helpers/in-memory-repositories.ts", "content": "/**\n * Repositorios en memoria para las pruebas unitarias.\n *\n * Implementan los MISMOS contratos (`CategoryRepository`, `ProductRepository`)\n * que usará Prisma en producción. Es la ventaja de la inversión de\n * dependencias: los casos de uso se prueban sin base de datos, rápido y de forma\n * determinista.\n *\n * Simulan también el comportamiento de PostgreSQL que los casos de uso esperan:\n *  - UNIQUE en `slug`  -> `ConflictError`\n *  - actualizar algo inexistente -> `NotFoundError`\n *  - clave foránea producto -> categoría -> `NotFoundError` si no existe\n *\n * Solo para pruebas: no se importa desde `src/`.\n */\n\nimport { randomUUID } from \"node:crypto\";\n\nimport type {\n  Category,\n  CategoryChanges,\n  NewCategory,\n} from \"../../../src/modules/categories/domain/category.ts\";\nimport type {\n  CategoryRepository,\n  ListCategoriesOptions,\n} from \"../../../src/modules/categories/domain/category-repository.ts\";\nimport type {\n  NewProduct,\n  Product,\n  ProductChanges,\n} from \"../../../src/modules/products/domain/product.ts\";\nimport type {\n  ListProductsOptions,\n  ProductRepository,\n} from \"../../../src/modules/products/domain/product-repository.ts\";\nimport { ConflictError, NotFoundError } from \"../../../src/modules/shared/domain/errors.ts\";\n\nexport class InMemoryCategoryRepository implements CategoryRepository {\n  readonly items = new Map<string, Category>();\n\n  async findById(id: string): Promise<Category | null> {\n    return this.items.get(id) ?? null;\n  }\n\n  async findBySlug(slug: string): Promise<Category | null> {\n    return [...this.items.values()].find((c) => c.slug === slug) ?? null;\n  }\n\n  async findAll(options: ListCategoriesOptions = {}): Promise<Category[]> {\n    const all = [...this.items.values()];\n    return options.onlyActive ? all.filter((c) => c.isActive) : all;\n  }\n\n  async create(data: NewCategory): Promise<Category> {\n    if (await this.findBySlug(data.slug)) throw new ConflictError(\"slug duplicado\");\n    const now = new Date();\n    const category: Category = { id: randomUUID(), ...data, createdAt: now, updatedAt: now };\n    this.items.set(category.id, category);\n    return category;\n  }\n\n  async update(id: string, changes: CategoryChanges): Promise<Category> {\n    const current = this.items.get(id);\n    if (!current) throw new NotFoundError(\"Categoría\", id);\n    if (changes.slug) {\n      const owner = await this.findBySlug(changes.slug);\n      if (owner && owner.id !== id) throw new ConflictError(\"slug duplicado\");\n    }\n    const updated: Category = { ...current, ...changes, updatedAt: new Date() };\n    this.items.set(id, updated);\n    return updated;\n  }\n}\n\nexport class InMemoryProductRepository implements ProductRepository {\n  readonly items = new Map<string, Product>();\n  /** Necesario para simular la clave foránea y el filtro `publicOnly`. */\n  private readonly categories: InMemoryCategoryRepository;\n\n  constructor(categories: InMemoryCategoryRepository) {\n    this.categories = categories;\n  }\n\n  async findById(id: string): Promise<Product | null> {\n    return this.items.get(id) ?? null;\n  }\n\n  async findBySlug(slug: string): Promise<Product | null> {\n    return [...this.items.values()].find((p) => p.slug === slug) ?? null;\n  }\n\n  async findAll(options: ListProductsOptions = {}): Promise<Product[]> {\n    let result = [...this.items.values()];\n    if (options.categoryId) result = result.filter((p) => p.categoryId === options.categoryId);\n    if (options.search) {\n      const term = options.search.toLowerCase();\n      result = result.filter((p) => p.name.toLowerCase().includes(term));\n    }\n    if (options.publicOnly) {\n      result = result.filter(\n        (p) => p.isAvailable && this.categories.items.get(p.categoryId)?.isActive === true,\n      );\n    }\n    return result;\n  }\n\n  async create(data: NewProduct): Promise<Product> {\n    if (!this.categories.items.has(data.categoryId)) {\n      throw new NotFoundError(\"Categoría\", data.categoryId); // clave foránea\n    }\n    if (await this.findBySlug(data.slug)) throw new ConflictError(\"slug duplicado\");\n    const now = new Date();\n    const product: Product = { id: randomUUID(), ...data, createdAt: now, updatedAt: now };\n    this.items.set(product.id, product);\n    return product;\n  }\n\n  async update(id: string, changes: ProductChanges): Promise<Product> {\n    const current = this.items.get(id);\n    if (!current) throw new NotFoundError(\"Producto\", id);\n    if (changes.slug) {\n      const owner = await this.findBySlug(changes.slug);\n      if (owner && owner.id !== id) throw new ConflictError(\"slug duplicado\");\n    }\n    const updated: Product = { ...current, ...changes, updatedAt: new Date() };\n    this.items.set(id, updated);\n    return updated;\n  }\n\n  async delete(id: string): Promise<void> {\n    if (!this.items.delete(id)) throw new NotFoundError(\"Producto\", id);\n  }\n}\n"}, {"path": "tests/unit/slug.test.ts", "content": "/**\n * Pruebas de las utilidades de slug (funciones puras del dominio compartido).\n */\n\nimport assert from \"node:assert/strict\";\nimport { describe, it } from \"node:test\";\n\nimport { ValidationError } from \"../../src/modules/shared/domain/errors.ts\";\nimport { isValidSlug, resolveSlug, slugify } from \"../../src/modules/shared/domain/slug.ts\";\n\ndescribe(\"slugify\", () => {\n  it(\"quita tildes y la ñ, y pasa a minúsculas\", () => {\n    assert.equal(slugify(\"Cumpleaños y Más\"), \"cumpleanos-y-mas\");\n  });\n\n  it(\"colapsa símbolos y espacios en un solo guion y recorta los bordes\", () => {\n    assert.equal(slugify(\"  ¡Caja   de  chocolates!!  \"), \"caja-de-chocolates\");\n  });\n\n  it(\"devuelve cadena vacía si no queda ningún carácter aprovechable\", () => {\n    assert.equal(slugify(\"¡¡¡???\"), \"\");\n  });\n\n  it(\"no supera la longitud máxima ni termina en guion\", () => {\n    const slug = slugify(\"a\".repeat(79) + \" b\");\n    assert.ok(slug.length <= 80);\n    assert.ok(!slug.endsWith(\"-\"));\n  });\n});\n\ndescribe(\"isValidSlug / resolveSlug\", () => {\n  it(\"acepta slugs bien formados y rechaza los mal formados\", () => {\n    assert.equal(isValidSlug(\"peluches-grandes\"), true);\n    for (const bad of [\"\", \"Peluches\", \"con espacios\", \"-inicio\", \"fin-\", \"doble--guion\", \"../etc\"]) {\n      assert.equal(isValidSlug(bad), false, bad);\n    }\n  });\n\n  it(\"usa el slug explícito si es válido, sin transformarlo\", () => {\n    assert.equal(resolveSlug(\"mi-slug\", \"Otro nombre\"), \"mi-slug\");\n  });\n\n  it(\"deriva el slug del nombre cuando no hay uno explícito\", () => {\n    assert.equal(resolveSlug(undefined, \"Taza Mágica\"), \"taza-magica\");\n    assert.equal(resolveSlug(\"   \", \"Taza Mágica\"), \"taza-magica\");\n  });\n\n  it(\"lanza ValidationError si el slug explícito es inválido o no se puede derivar\", () => {\n    assert.throws(() => resolveSlug(\"Mal Slug\", \"x\"), ValidationError);\n    assert.throws(() => resolveSlug(undefined, \"???\"), ValidationError);\n  });\n});\n"}, {"path": "tests/unit/category.test.ts", "content": "/**\n * Pruebas de los casos de uso de categorías, con repositorio en memoria.\n */\n\nimport assert from \"node:assert/strict\";\nimport { beforeEach, describe, it } from \"node:test\";\n\nimport { CreateCategory } from \"../../src/modules/categories/application/create-category.ts\";\nimport { GetCategoryById } from \"../../src/modules/categories/application/get-category-by-id.ts\";\nimport { GetCategoryBySlug } from \"../../src/modules/categories/application/get-category-by-slug.ts\";\nimport { ListCategories } from \"../../src/modules/categories/application/list-categories.ts\";\nimport {\n  DeactivateCategory,\n  ReactivateCategory,\n} from \"../../src/modules/categories/application/set-category-status.ts\";\nimport { UpdateCategory } from \"../../src/modules/categories/application/update-category.ts\";\nimport {\n  ConflictError,\n  NotFoundError,\n  ValidationError,\n} from \"../../src/modules/shared/domain/errors.ts\";\nimport { InMemoryCategoryRepository } from \"./helpers/in-memory-repositories.ts\";\n\nlet categories: InMemoryCategoryRepository;\nlet create: CreateCategory;\n\nbeforeEach(() => {\n  categories = new InMemoryCategoryRepository();\n  create = new CreateCategory({ categories });\n});\n\ndescribe(\"CreateCategory\", () => {\n  it(\"crea una categoría activa y deriva el slug del nombre\", async () => {\n    const category = await create.execute({ name: \"  Cumpleaños  \", description: \"  \" });\n    assert.equal(category.name, \"Cumpleaños\");\n    assert.equal(category.slug, \"cumpleanos\");\n    assert.equal(category.description, null);\n    assert.equal(category.isActive, true);\n  });\n\n  it(\"rechaza nombres vacíos o solo espacios\", async () => {\n    await assert.rejects(create.execute({ name: \"   \" }), ValidationError);\n  });\n\n  it(\"rechaza un slug explícito inválido\", async () => {\n    await assert.rejects(create.execute({ name: \"Flores\", slug: \"Flores!\" }), ValidationError);\n  });\n\n  it(\"no permite duplicar el slug\", async () => {\n    await create.execute({ name: \"Peluches\" });\n    await assert.rejects(create.execute({ name: \"Peluches\" }), ConflictError);\n    await assert.rejects(create.execute({ name: \"Otro\", slug: \"peluches\" }), ConflictError);\n  });\n});\n\ndescribe(\"consultas\", () => {\n  it(\"obtiene por id y por slug, y lanza NotFoundError si no existe\", async () => {\n    const created = await create.execute({ name: \"Flores\" });\n    assert.equal((await new GetCategoryById({ categories }).execute(created.id)).id, created.id);\n    assert.equal((await new GetCategoryBySlug({ categories }).execute(\"flores\")).id, created.id);\n    await assert.rejects(new GetCategoryById({ categories }).execute(\"nope\"), NotFoundError);\n    await assert.rejects(new GetCategoryBySlug({ categories }).execute(\"nope\"), NotFoundError);\n  });\n\n  it(\"lista solo las activas cuando se pide\", async () => {\n    const a = await create.execute({ name: \"A\" });\n    await create.execute({ name: \"B\" });\n    await new DeactivateCategory({ categories }).execute(a.id);\n\n    const list = new ListCategories({ categories });\n    assert.equal((await list.execute()).length, 2);\n    assert.deepEqual((await list.execute({ onlyActive: true })).map((c) => c.name), [\"B\"]);\n  });\n});\n\ndescribe(\"UpdateCategory\", () => {\n  it(\"cambia el nombre pero conserva el slug (URLs estables)\", async () => {\n    const created = await create.execute({ name: \"Flores\" });\n    const updated = await new UpdateCategory({ categories }).execute(created.id, {\n      name: \"Flores y plantas\",\n    });\n    assert.equal(updated.name, \"Flores y plantas\");\n    assert.equal(updated.slug, \"flores\");\n  });\n\n  it(\"rechaza un slug que pertenece a otra categoría\", async () => {\n    await create.execute({ name: \"Flores\" });\n    const other = await create.execute({ name: \"Peluches\" });\n    await assert.rejects(\n      new UpdateCategory({ categories }).execute(other.id, { slug: \"flores\" }),\n      ConflictError,\n    );\n  });\n\n  it(\"permite reenviar su propio slug sin error\", async () => {\n    const created = await create.execute({ name: \"Flores\" });\n    const updated = await new UpdateCategory({ categories }).execute(created.id, { slug: \"flores\" });\n    assert.equal(updated.slug, \"flores\");\n  });\n\n  it(\"lanza NotFoundError si la categoría no existe y ValidationError si el nombre es vacío\", async () => {\n    const useCase = new UpdateCategory({ categories });\n    await assert.rejects(useCase.execute(\"nope\", { name: \"X\" }), NotFoundError);\n    const created = await create.execute({ name: \"Flores\" });\n    await assert.rejects(useCase.execute(created.id, { name: \" \" }), ValidationError);\n  });\n});\n\ndescribe(\"desactivar y reactivar\", () => {\n  it(\"desactiva sin borrar y es idempotente; luego reactiva\", async () => {\n    const created = await create.execute({ name: \"Flores\" });\n    const deactivate = new DeactivateCategory({ categories });\n\n    assert.equal((await deactivate.execute(created.id)).isActive, false);\n    assert.equal((await deactivate.execute(created.id)).isActive, false);\n    assert.equal(categories.items.size, 1);\n\n    assert.equal((await new ReactivateCategory({ categories }).execute(created.id)).isActive, true);\n  });\n\n  it(\"lanza NotFoundError si no existe\", async () => {\n    await assert.rejects(new DeactivateCategory({ categories }).execute(\"nope\"), NotFoundError);\n  });\n});\n"}, {"path": "tests/unit/product.test.ts", "content": "/**\n * Pruebas de los casos de uso de productos, con repositorios en memoria.\n *\n * Cubren las reglas pedidas: categoría inexistente, categoría inactiva, precios\n * inválidos, slugs únicos y manejo de errores del dominio.\n */\n\nimport assert from \"node:assert/strict\";\nimport { beforeEach, describe, it } from \"node:test\";\n\nimport { DeactivateCategory } from \"../../src/modules/categories/application/set-category-status.ts\";\nimport { CreateCategory } from \"../../src/modules/categories/application/create-category.ts\";\nimport type { Category } from \"../../src/modules/categories/domain/category.ts\";\nimport { CreateProduct, type CreateProductInput } from \"../../src/modules/products/application/create-product.ts\";\nimport { DeactivateProduct } from \"../../src/modules/products/application/deactivate-product.ts\";\nimport { DeleteProduct } from \"../../src/modules/products/application/delete-product.ts\";\nimport { GetProductById } from \"../../src/modules/products/application/get-product-by-id.ts\";\nimport { GetProductBySlug } from \"../../src/modules/products/application/get-product-by-slug.ts\";\nimport { ListProducts } from \"../../src/modules/products/application/list-products.ts\";\nimport { UpdateProduct } from \"../../src/modules/products/application/update-product.ts\";\nimport { PRODUCT_PRICE_MAX_IN_CENTS } from \"../../src/modules/products/domain/product.ts\";\nimport {\n  BusinessRuleError,\n  ConflictError,\n  DomainError,\n  NotFoundError,\n  ValidationError,\n} from \"../../src/modules/shared/domain/errors.ts\";\nimport {\n  InMemoryCategoryRepository,\n  InMemoryProductRepository,\n} from \"./helpers/in-memory-repositories.ts\";\n\nlet categories: InMemoryCategoryRepository;\nlet products: InMemoryProductRepository;\nlet category: Category;\nlet createProduct: CreateProduct;\n\n/** Producto válido de base; cada prueba sobrescribe solo lo que le interesa. */\nfunction validInput(overrides: Partial<CreateProductInput> = {}): CreateProductInput {\n  return {\n    name: \"Caja de chocolates\",\n    description: \"Surtido de 12 chocolates artesanales.\",\n    priceInCents: 4_590_000, // $45.900 COP\n    categoryId: category.id,\n    ...overrides,\n  };\n}\n\nbeforeEach(async () => {\n  categories = new InMemoryCategoryRepository();\n  products = new InMemoryProductRepository(categories);\n  category = await new CreateCategory({ categories }).execute({ name: \"Dulces\" });\n  createProduct = new CreateProduct({ products, categories });\n});\n\ndescribe(\"CreateProduct\", () => {\n  it(\"crea un producto válido, deriva el slug y lo deja disponible\", async () => {\n    const product = await createProduct.execute(validInput());\n    assert.equal(product.slug, \"caja-de-chocolates\");\n    assert.equal(product.priceInCents, 4_590_000);\n    assert.equal(product.isAvailable, true);\n    assert.equal(product.imageUrl, null);\n  });\n\n  it(\"rechaza una categoría inexistente\", async () => {\n    await assert.rejects(createProduct.execute(validInput({ categoryId: \"no-existe\" })), NotFoundError);\n    assert.equal(products.items.size, 0);\n  });\n\n  it(\"rechaza una categoría inactiva\", async () => {\n    await new DeactivateCategory({ categories }).execute(category.id);\n    await assert.rejects(createProduct.execute(validInput()), BusinessRuleError);\n    assert.equal(products.items.size, 0);\n  });\n\n  it(\"rechaza precios inválidos\", async () => {\n    const invalidPrices = [0, -100, 10.5, Number.NaN, Number.POSITIVE_INFINITY, PRODUCT_PRICE_MAX_IN_CENTS + 1];\n    for (const priceInCents of invalidPrices) {\n      await assert.rejects(\n        createProduct.execute(validInput({ priceInCents, name: `Producto ${String(priceInCents)}` })),\n        ValidationError,\n        `precio ${String(priceInCents)}`,\n      );\n    }\n    assert.equal(products.items.size, 0);\n  });\n\n  it(\"acepta el precio máximo permitido\", async () => {\n    const product = await createProduct.execute(validInput({ priceInCents: PRODUCT_PRICE_MAX_IN_CENTS }));\n    assert.equal(product.priceInCents, PRODUCT_PRICE_MAX_IN_CENTS);\n  });\n\n  it(\"rechaza nombre vacío\", async () => {\n    await assert.rejects(createProduct.execute(validInput({ name: \"   \" })), ValidationError);\n  });\n\n  it(\"no permite duplicar el slug\", async () => {\n    await createProduct.execute(validInput());\n    await assert.rejects(createProduct.execute(validInput()), ConflictError);\n    await assert.rejects(\n      createProduct.execute(validInput({ name: \"Otra caja\", slug: \"caja-de-chocolates\" })),\n      ConflictError,\n    );\n  });\n\n  it(\"rechaza URLs de imagen con esquemas peligrosos o mal formadas\", async () => {\n    for (const imageUrl of [\"javascript:alert(1)\", \"data:text/html;base64,AAAA\", \"no es una url\"]) {\n      await assert.rejects(\n        createProduct.execute(validInput({ imageUrl, name: `P ${imageUrl}` })),\n        ValidationError,\n        imageUrl,\n      );\n    }\n    const ok = await createProduct.execute(validInput({ imageUrl: \"https://cdn.ejemplo.com/a.jpg\" }));\n    assert.equal(ok.imageUrl, \"https://cdn.ejemplo.com/a.jpg\");\n  });\n\n  it(\"todos los errores de negocio son DomainError (el borde puede traducirlos a HTTP)\", async () => {\n    await assert.rejects(createProduct.execute(validInput({ priceInCents: 0 })), (error: unknown) => {\n      assert.ok(error instanceof DomainError);\n      assert.equal(error.code, \"VALIDATION\");\n      return true;\n    });\n  });\n});\n\ndescribe(\"consultas y listado\", () => {\n  it(\"obtiene por id y por slug; NotFoundError si no existe\", async () => {\n    const product = await createProduct.execute(validInput());\n    assert.equal((await new GetProductById({ products }).execute(product.id)).id, product.id);\n    assert.equal((await new GetProductBySlug({ products }).execute(product.slug)).id, product.id);\n    await assert.rejects(new GetProductById({ products }).execute(\"nope\"), NotFoundError);\n    await assert.rejects(new GetProductBySlug({ products }).execute(\"nope\"), NotFoundError);\n  });\n\n  it(\"el listado público oculta productos no disponibles y los de categorías inactivas\", async () => {\n    const visible = await createProduct.execute(validInput({ name: \"Visible\" }));\n    const hidden = await createProduct.execute(validInput({ name: \"Oculto\" }));\n    await new DeactivateProduct({ products }).execute(hidden.id);\n\n    const other = await new CreateCategory({ categories }).execute({ name: \"Flores\" });\n    await createProduct.execute(validInput({ name: \"Rosas\", categoryId: other.id }));\n    await new DeactivateCategory({ categories }).execute(other.id);\n\n    const list = new ListProducts({ products });\n    assert.equal((await list.execute()).length, 3);\n    assert.deepEqual((await list.execute({ publicOnly: true })).map((p) => p.id), [visible.id]);\n  });\n\n  it(\"filtra por categoría y por texto, ignorando búsquedas en blanco\", async () => {\n    await createProduct.execute(validInput({ name: \"Chocolate negro\" }));\n    await createProduct.execute(validInput({ name: \"Galletas\" }));\n    const list = new ListProducts({ products });\n    assert.equal((await list.execute({ categoryId: category.id })).length, 2);\n    assert.deepEqual((await list.execute({ search: \"  CHOCO \" })).map((p) => p.name), [\"Chocolate negro\"]);\n    assert.equal((await list.execute({ search: \"   \" })).length, 2);\n  });\n});\n\ndescribe(\"UpdateProduct\", () => {\n  let update: UpdateProduct;\n  beforeEach(() => {\n    update = new UpdateProduct({ products, categories });\n  });\n\n  it(\"actualiza precio y nombre, y conserva el slug\", async () => {\n    const product = await createProduct.execute(validInput());\n    const updated = await update.execute(product.id, { name: \"Chocolates premium\", priceInCents: 5_000_000 });\n    assert.equal(updated.name, \"Chocolates premium\");\n    assert.equal(updated.priceInCents, 5_000_000);\n    assert.equal(updated.slug, \"caja-de-chocolates\");\n  });\n\n  it(\"rechaza precio inválido sin modificar el producto\", async () => {\n    const product = await createProduct.execute(validInput());\n    await assert.rejects(update.execute(product.id, { priceInCents: -5 }), ValidationError);\n    assert.equal((await products.findById(product.id))?.priceInCents, 4_590_000);\n  });\n\n  it(\"rechaza mover el producto a una categoría inexistente o inactiva\", async () => {\n    const product = await createProduct.execute(validInput());\n    await assert.rejects(update.execute(product.id, { categoryId: \"nope\" }), NotFoundError);\n\n    const inactive = await new CreateCategory({ categories }).execute({ name: \"Retirada\" });\n    await new DeactivateCategory({ categories }).execute(inactive.id);\n    await assert.rejects(update.execute(product.id, { categoryId: inactive.id }), BusinessRuleError);\n  });\n\n  it(\"permite editar un producto cuya categoría actual fue desactivada\", async () => {\n    const product = await createProduct.execute(validInput());\n    await new DeactivateCategory({ categories }).execute(category.id);\n    const updated = await update.execute(product.id, { description: \"Nueva descripción\" });\n    assert.equal(updated.description, \"Nueva descripción\");\n  });\n\n  it(\"rechaza un slug que pertenece a otro producto\", async () => {\n    await createProduct.execute(validInput({ name: \"Uno\" }));\n    const two = await createProduct.execute(validInput({ name: \"Dos\" }));\n    await assert.rejects(update.execute(two.id, { slug: \"uno\" }), ConflictError);\n  });\n\n  it(\"lanza NotFoundError si el producto no existe\", async () => {\n    await assert.rejects(update.execute(\"nope\", { name: \"X\" }), NotFoundError);\n  });\n\n  it(\"puede quitar la imagen enviando null\", async () => {\n    const product = await createProduct.execute(validInput({ imageUrl: \"https://cdn.ejemplo.com/a.jpg\" }));\n    const updated = await update.execute(product.id, { imageUrl: null });\n    assert.equal(updated.imageUrl, null);\n  });\n});\n\ndescribe(\"desactivar y eliminar\", () => {\n  it(\"desactivar conserva el registro y es idempotente\", async () => {\n    const product = await createProduct.execute(validInput());\n    const deactivate = new DeactivateProduct({ products });\n    assert.equal((await deactivate.execute(product.id)).isAvailable, false);\n    assert.equal((await deactivate.execute(product.id)).isAvailable, false);\n    assert.equal(products.items.size, 1);\n  });\n\n  it(\"eliminar borra el registro; NotFoundError si no existe\", async () => {\n    const product = await createProduct.execute(validInput());\n    await new DeleteProduct({ products }).execute(product.id);\n    assert.equal(products.items.size, 0);\n    await assert.rejects(new DeleteProduct({ products }).execute(product.id), NotFoundError);\n    await assert.rejects(new DeactivateProduct({ products }).execute(\"nope\"), NotFoundError);\n  });\n});\n"}];
for (const { path, content } of FILES) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log(`escrito ${path}`);
}
console.log("\nListo. Ahora ejecuta:  npm install  &&  npm run typecheck  &&  npm test");
